<style>
:root { color-scheme:light; --paper:#fff; --soft:#f6f8f8; --ink:#202b2e; --muted:#59676c; --line:#e3e8e8; --accent:#096956; --selection:#e9f4f0; }
[data-theme=dark] { color-scheme:dark; --paper:#151b1e; --soft:#1c2428; --ink:#e7edef; --muted:#acbcc2; --line:#303c41; --accent:#8bd8bf; --selection:#203c33; }
* { box-sizing:border-box; } body { margin:0; background:var(--paper); color:var(--ink); font:15px/1.85 'Noto Sans Thai',system-ui,sans-serif; } a { color:var(--accent); text-underline-offset:4px; } button { font:inherit; cursor:pointer; } :focus-visible { outline:2px solid var(--accent); outline-offset:4px; } .skip { position:fixed; top:-80px; left:15px; padding:10px; z-index:3; background:var(--paper); } .skip:focus { top:10px; }
.topbar { height:76px; position:sticky; top:0; z-index:2; background:var(--paper); border-bottom:1px solid var(--line); display:flex; align-items:center; justify-content:space-between; gap:16px; padding:0 36px; } .brand { display:flex; align-items:center; gap:13px; color:var(--ink); text-decoration:none; font-size:17px; } .brand-mark { background:var(--ink); color:var(--paper); width:34px; height:34px; display:grid; place-items:center; font-size:13px; border-radius:8px; font-weight:700; } .brand-divider { color:var(--muted); } .header-actions { display:flex; gap:22px; align-items:center; font-size:13px; } #theme-toggle { padding:7px 10px; border:0; background:var(--soft); color:var(--muted); border-radius:6px; font-size:12px; } .open-app { color:var(--ink); text-decoration:none; font-weight:600; }
.docs-layout { display:grid; grid-template-columns:245px minmax(0,820px); column-gap:72px; max-width:1290px; margin:auto; padding:0 32px; } .sidebar { position:sticky; top:76px; height:calc(100vh - 76px); overflow-y:auto; padding:30px 24px 30px 0; border-right:1px solid var(--line); font-size:13px; } .sidebar summary { font-weight:600; cursor:pointer; list-style:none; margin-bottom:20px; } .nav-group { font-size:11px; color:var(--muted); margin:26px 10px 9px; font-weight:600; } .sidebar nav a { display:flex; align-items:center; justify-content:space-between; padding:7px 10px; margin:3px 0; border-radius:6px; color:var(--muted); text-decoration:none; } .sidebar nav a:hover { color:var(--ink); background:var(--soft); } .sidebar nav a[aria-current] { background:var(--selection); color:var(--accent); font-weight:600; } .new-label { color:var(--accent); font-size:10px; } .sidebar-bottom { margin-top:36px; border-top:1px solid var(--line); padding:22px 10px 0; } .sidebar-bottom span { display:block; color:var(--muted); font-size:11px; margin-bottom:8px; } .sidebar-bottom a { display:block; font-size:12px; text-decoration:none; padding:4px 0; }
main { min-width:0; padding:43px 0 0; } .breadcrumb { font-size:12px; color:var(--muted); margin-bottom:32px; } .breadcrumb span { margin:0 12px; color:var(--line); } section { scroll-margin-top:104px; padding:25px 0 34px; border-bottom:1px solid var(--line); } .intro { padding-top:0; } .heading-meta { display:flex; align-items:center; flex-wrap:wrap; gap:14px; color:var(--muted); font-size:11px; } .tag { padding:3px 9px; border-radius:5px; background:var(--selection); color:var(--accent); font-weight:600; } h1,h2,h3 { line-height:1.4; text-wrap:balance; } h1 { font-size:38px; letter-spacing:-.025em; margin:22px 0 16px; font-weight:700; } h2 { font-size:24px; margin:16px 0; font-weight:600; } h3 { font-size:17px; margin-top:26px; } p { max-width:72ch; margin:13px 0; } .lead { font-size:17px; color:var(--muted); max-width:58ch; } .intro-actions { display:flex; flex-wrap:wrap; gap:22px; align-items:center; margin:25px 0 28px; } .primary { display:inline-flex; gap:24px; align-items:center; background:var(--accent); color:var(--paper); padding:10px 16px; border-radius:7px; text-decoration:none; font-weight:600; font-size:13px; } .text-link { font-size:13px; } .callout { background:var(--soft); padding:18px 20px; border-radius:8px; font-size:13px; margin:24px 0 4px; } .callout p { margin:6px 0 0; color:var(--muted); } .section-kicker { color:var(--muted); font-size:11px; margin-top:12px; } .caption { font-size:12px; color:var(--muted); } .steps { padding-left:23px; } .steps li { margin:10px 0; padding-left:5px; } code { font:12px/1.7 ui-monospace,SFMono-Regular,Consolas,monospace; overflow-wrap:anywhere; } p>code,li>code,td>code { background:var(--soft); padding:2px 5px; border-radius:4px; }
.code-block { margin:22px 0 15px; border:1px solid var(--line); border-radius:8px; overflow:hidden; background:var(--soft); } .code-toolbar { display:flex; justify-content:space-between; gap:12px; align-items:center; padding:8px 15px; border-bottom:1px solid var(--line); color:var(--muted); font-size:11px; } .code-toolbar button { display:flex; align-items:center; gap:10px; border:1px solid var(--line); background:var(--paper); color:var(--ink); border-radius:5px; padding:4px 9px; font-size:11px; } .code-toolbar button:hover { border-color:var(--accent); } pre { margin:0; padding:20px; overflow-x:auto; line-height:1.7; tab-size:2; } pre code { white-space:pre; overflow-wrap:normal; }
.table-scroll { overflow:auto; } table { width:100%; border-collapse:collapse; font-size:12px; text-align:left; margin:24px 0; } th { font-weight:600; background:var(--soft); } th,td { border-bottom:1px solid var(--line); padding:12px 14px; vertical-align:top; } .troubleshooting details { border-bottom:1px solid var(--line); padding:15px 0; } .troubleshooting summary { cursor:pointer; font-weight:500; font-size:14px; } .troubleshooting p { color:var(--muted); font-size:13px; } .doc-footer { display:flex; flex-wrap:wrap; justify-content:space-between; gap:12px; padding:32px 0 42px; font-size:11px; color:var(--muted); } .copy-status { position:fixed; right:20px; bottom:20px; max-width:calc(100vw - 40px); padding:10px 18px; background:var(--ink); color:var(--paper); border-radius:7px; font-size:13px; opacity:0; pointer-events:none; transition:opacity .15s ease; z-index:3; } .copy-status.visible { opacity:1; }
@media(max-width:1050px) { .docs-layout { column-gap:35px; grid-template-columns:205px minmax(0,1fr); } .topbar { padding:0 24px; } h1 { font-size:32px; } }
@media(max-width:720px) { .topbar { height:64px; padding:0 16px; gap:10px; } .brand { font-size:14px; gap:8px; } .brand-mark { width:28px; height:28px; font-size:11px; } .header-actions { gap:8px; } .open-app { font-size:11px; } #theme-toggle { font-size:10px; padding:6px; } .docs-layout { display:block; padding:0 20px; } .sidebar { position:static; height:auto; padding:18px 0; border-right:0; border-bottom:1px solid var(--line); } .sidebar summary { margin:0; list-style:revert; } .sidebar nav { display:grid; grid-template-columns:1fr 1fr; gap:2px 12px; padding-top:12px; } .nav-group { grid-column:1/-1; margin-top:15px; } .sidebar-bottom { display:none; } main { padding-top:25px; } .breadcrumb { margin-bottom:23px; } h1 { font-size:30px; } h2 { font-size:22px; } .lead { font-size:15px; } section { scroll-margin-top:85px; } pre { padding:15px; } }
@media(prefers-reduced-motion:reduce) { * { transition:none!important; } }
</style>
